            "def": "CREATE OR REPLACE FUNCTION public.apply_morphological_rule_dispatcher_to_analysis_v3(p_analysis jsonb, p_release_code text)\\n RETURNS jsonb\\n LANGUAGE plpgsql\\n STABLE\\n SET search_path TO 'public', 'pg_catalog'\\nAS $function$\\ndeclare m jsonb; outm jsonb:='[]'::jsonb; d jsonb; st text; features jsonb; selected jsonb; pos text;\\nbegin\\n for m in select value from jsonb_array_elements(coalesce(p_analysis#>'{language_graph,morphology_v1}','[]'::jsonb)) order by nullif(value->>'token_index','')::int loop\\n   pos:=coalesce(m->>'selected_source_pos',m#>>'{selected_reading,source_pos}');\\n   d:=public.dispatch_morphological_rules_v3(m->>'surface',m->>'selected_lemma',pos,p_release_code);\\n   m:=jsonb_set(m,'{runtime_rule_evidence,morphological_dispatcher_v3}',d,true);\\n   st:=m->>'status';\\n   if st in ('ambiguous','no_morph_reading') and d->>'status'='resolved' and d#>'{selected,features}' is not null and d#>'{selected,features}'<>'null'::jsonb then\\n     features:=d#>'{selected,features}'; pos:=d#>>'{selected,lexeme_pos}';\\n     selected:=jsonb_build_object('lemma',d#>>'{lexeme_resolution,lemma}','features',features,'reading_id','runtime_rule:'||(d#>>'{selected,target_form_key}'),'source_pos',pos,\\n       'reading_key','runtime_rule:'||(d#>>'{selected,rule_code}'),'candidate_id',null,'source_form_type',d#>>'{selected,target_form_key}');\\n     m:=m||jsonb_build_object('status','resolved_by_runtime_rule_evidence','confidence','high','selected_lemma',d#>>'{lexeme_resolution,lemma}',\\n       'selected_reading',selected,'selected_reading_id',selected->>'reading_id','selected_source_pos',pos,'selected_reading_key',selected->>'reading_key','selected_candidate_id',null,\\n       'surviving_readings',jsonb_build_array(selected),'surviving_count',1);\\n   end if;\\n   outm:=outm||jsonb_build_array(m);\\n end loop;\\n p_analysis:=jsonb_set(p_analysis,'{language_graph,morphology_v1}',outm,true);\\n return jsonb_set(p_analysis,'{language_graph,morphological_rule_dispatcher_v3}',jsonb_build_object('version','morphological-rule-dispatcher-v3','release_code',p_release_code,'status','applied_at_canonical_morphology_stage','resolver','generic-pos-aware'),true);\\nend;$function$\\n",
