            "def": "CREATE OR REPLACE FUNCTION public.dispatch_morphological_rules_v3(p_surface text, p_selected_lemma text, p_selected_pos text, p_release_code text)\\n RETURNS jsonb\\n LANGUAGE plpgsql\\n STABLE\\n SET search_path TO 'public', 'pg_catalog'\\nAS $function$\\ndeclare lx jsonb; lid uuid; lpos text; r record; a record; src text; tgt text; intermediate text; final_form text; items jsonb:='[]'::jsonb; matched jsonb:='[]'::jsonb; top_priority int; distinct_features int; chosen jsonb; features jsonb;\\nbegin\\n lx:=public.resolve_lexeme_for_surface_v1(p_surface,p_selected_lemma,p_selected_pos);\\n lid:=nullif(lx->>'lexeme_id','')::uuid; lpos:=lx->>'pos';\\n if lid is null then return jsonb_build_object('version','morphological-rule-dispatcher-v3','status','no_evidence','lexeme_resolution',lx,'matches','[]'::jsonb); end if;\\n for r in\\n   select gr.id,gr.code,gr.priority,gr.pattern,coalesce(rr.metadata,'{}'::jsonb) membership\\n   from public.grammar_runtime_releases rel join public.grammar_runtime_release_rules rr on rr.release_id=rel.id and rr.is_enabled\\n   join public.grammar_rules gr on gr.id=rr.rule_id\\n   where rel.code=p_release_code and gr.pattern_type='morphological_inflection'\\n     and coalesce(rr.metadata->>'composition_role',gr.pattern->>'composition_role','primary')='primary'\\n   order by gr.priority desc,gr.code\\n loop\\n   if not exists(select 1 from public.grammar_morph_form_registry_v1 x where x.pos=lpos and x.form_key=r.pattern->>'source_form_key' and x.is_active)\\n      or not exists(select 1 from public.grammar_morph_form_registry_v1 x where x.pos=lpos and x.form_key=r.pattern->>'target_form_key' and x.is_active) then continue; end if;\\n   select f.value into src from public.lexeme_form_variants f where f.lexeme_id=lid and f.form_key=r.pattern->>'source_form_key' and f.verification_status='source_verified' order by f.is_primary desc nulls last,f.is_main desc nulls last,f.variant_rank nulls last,f.value limit 1;\\n   select f.value into tgt from public.lexeme_form_variants f where f.lexeme_id=lid and f.form_key=r.pattern->>'target_form_key' and f.verification_status='source_verified' order by f.is_primary desc nulls last,f.is_main desc nulls last,f.variant_rank nulls last,f.value limit 1;\\n   if src is null or tgt is null then continue; end if;\\n   intermediate:=public.apply_morph_string_operation_v1(src,r.pattern); features:=public.morph_form_key_features_v2(lpos,r.pattern->>'target_form_key');\\n   items:=items||jsonb_build_array(jsonb_build_object('rule_code',r.code,'lexeme_pos',lpos,'source_form',src,'target_form',tgt,'intermediate',intermediate,'composition_domain',r.membership->>'composition_domain','composition_group',r.membership->>'composition_group'));\\n   if intermediate=tgt and lower(tgt)=lower(p_surface) then\\n     matched:=matched||jsonb_build_array(jsonb_build_object('rule_id',r.id,'rule_code',r.code,'priority',r.priority,'target_form_key',r.pattern->>'target_form_key','features',features,'execution_path','direct','source_form',src,'target_form',tgt,'lexeme_pos',lpos));\\n   elsif intermediate is not null and intermediate<>tgt and lower(tgt)=lower(p_surface) and nullif(r.membership->>'composition_group','') is not null then\\n     for a in\\n       select gr.id,gr.code,gr.priority,gr.pattern,coalesce(rr.metadata,'{}'::jsonb) membership\\n       from public.grammar_runtime_releases rel2 join public.grammar_runtime_release_rules rr on rr.release_id=rel2.id and rr.is_enabled\\n       join public.grammar_rules gr on gr.id=rr.rule_id\\n       where rel2.code=p_release_code and gr.pattern_type='morphological_inflection'\\n         and coalesce(rr.metadata->>'composition_role',gr.pattern->>'composition_role')='post_transform_adjustment'\\n         and rr.metadata->>'composition_domain'=r.membership->>'composition_domain'\\n         and rr.metadata->>'composition_group'=r.membership->>'composition_group'\\n       order by gr.priority desc,gr.code\\n     loop\\n       final_form:=public.apply_morph_string_operation_v1(intermediate,a.pattern);\\n       if final_form=tgt then matched:=matched||jsonb_build_array(jsonb_build_object('rule_id',r.id,'rule_code',r.code,'priority',greatest(r.priority,a.priority),'target_form_key',r.pattern->>'target_form_key','features',features,'execution_path','composed_two_step','source_form',src,'intermediate_form',intermediate,'target_form',tgt,'lexeme_pos',lpos,'composition_rule_id',a.id,'composition_rule_code',a.code,'composition_domain',r.membership->>'composition_domain','composition_group',r.membership->>'composition_group')); end if;\\n     end loop;\\n   end if;\\n end loop;\\n if jsonb_array_length(matched)=0 then return jsonb_build_object('version','morphological-rule-dispatcher-v3','status','no_match','lexeme_resolution',lx,'evaluated',items,'matches',matched); end if;\\n select max((x->>'priority')::int) into top_priority from jsonb_array_elements(matched) x;\\n select count(distinct coalesce(x->'features','null'::jsonb)) into distinct_features from jsonb_array_elements(matched) x where (x->>'priority')::int=top_priority;\\n if distinct_features>1 then return jsonb_build_object('version','morphological-rule-dispatcher-v3','status','conflict','priority',top_priority,'lexeme_resolution',lx,'matches',matched); end if;\\n select x into chosen from jsonb_array_elements(matched) x where (x->>'priority')::int=top_priority order by case when x->>'execution_path'='composed_two_step' then 0 else 1 end,x->>'rule_code' limit 1;\\n return jsonb_build_object('version','morphological-rule-dispatcher-v3','status','resolved','priority',top_priority,'lexeme_resolution',lx,'selected',chosen,'matches',matched,'evaluated',items);\\nend;$function$\\n",
